function talkDad(){
  const F=G.f;
  if(!Rg.namesBack()){
    // 넋이 빠진 아빠는 무엇으로 와도 돌아보지 않는다. 모자를 보이려면 본모습이어야 한다
    if(G.form){talk([['아빠','(아빠는 호수만 본다. 돌아보지 않는다.)']]);return;}
    if(!F.dadDone){dadMeet();return;}
    const c=dadArcChoices();
    const idle=[['아빠',['(아빠가 매듭을 묶었다 푼다.)','(아빠가 막대에 금을 하나 긋는다.)','(아빠는 호수만 본다.)'][(G.f.yDadIdle=(G.f.yDadIdle||0)+1)%3]]];
    if(c.length){talk([[...idle[0],[...c,{t:'아빠 곁에 앉아 있는다',go:null}]]]);return;}
    talk(idle);return;
  }
  // 아빠는 집안 사람이라 변신한 아이를 알아본다 (leaf-transform.md 6-4).
  if(G.form){talk([['아빠','(아빠가 보따리 끈의 잎사귀를 손가락으로 톡 친다.)\n…다 보인다.']]);return;}
  const c=dadArcChoices();
  if(c.length){talk([['아빠','(아빠가 나를 보고 고개를 든다.)',[...c,{t:'아빠 곁에 있는다',go:dadMain}]]]);return;}
  dadMain();
}
function dadMain(){
  const F=G.f;
  if(!F.fruitGot){talk([['아빠','열매부터.\n…다녀와. 여기 있으마.']]);return;}
  if(!F.nameGiven){talk([['아빠','(아빠가 신목 쪽을 보다 말고 내 손을 꼭 쥔다.\n한참 만에야 손을 놓는다.)']]);return;}
  if(F.yakDone){returnPrep();return;}
  talk([['아빠','절구 꺼내라.\n…같이 찧자.']],makeReturningMedicine);
}
/* 결정 D-437: 강철이를 물리치거나 달래면 아빠가 이름을 되찾는다. 아이 보따리 끈의 짐표 앞면에 글씨가 먼저 돌아온다(이름의 규칙 6).
   얼음이 풀린 물을 헤치고 아빠가 섬 기슭으로 올라온다. 이번엔 부르면 돌아본다. 아빠는 말을 값으로 낸 적이 없어 말을 한다. 다만 짧게. */
/* 결정 D-438: 이름을 되찾는 장면·마지막 셈·절구 약·귀향 대화가 도는 동안은 교환과 건네기 단추를 닫는다(D-197 tradeClosedNow).
   교환 단추로 장면을 닫으면 셈 뒤 약 장면이 끊긴다. 대화가 닫히면 ambient 에서 푼다. */
let climax=false;
const climaxOn=()=>{climax=true;};
Rg.tradeClosed=()=>climax;
Rg.clearClimax=()=>{if(climax&&!open('dlg'))climax=false;};
function dadComesBack(next){
  const F=G.f;if(F.dadBack){next?.();return;}
  climaxOn();
  F.dadBack=true;learn('dad:back');
  diary('y_dad_back','강철이가 입을 벌리자 삼킨 이름들이 쏟아졌다. 짐표 앞면에 아빠 이름이 돌아왔다. 나는 왜 그걸 잊고 있었을까. 아빠가 물을 헤치고 와서, 이번엔 부르니 돌아보았다.');
  talk([['너구리','(보따리 끈의 짐표가 따뜻하다.\n매끈하던 앞면에… 글씨가 있다.)'],
    ['너구리','(아빠 이름이다. 먹빛이 또렷하다.\n…나는 왜 이걸 잊고 있었지?)'],
    ['너구리','(얼음 녹은 물을 헤치고\n누가 섬 기슭으로 올라온다.)'],
    ['너구리','아빠!'],
    ['아빠','(아빠가 돌아본다.)'],
    ['아빠','(아빠가 나를 한참 본다.\n손이 내 모자 챙에 닿는다.)'],
    ['아빠','…모자, 잘 맞네.'],
    ['너구리','…헐렁해요.'],
    ['아빠','(아빠가 짧게 웃는다. 소리가 난다.)'],
    ['아빠','어미는.'],
    ['너구리','집에 있어요. 말을 자꾸 잃어요.\n약 지으러 왔어요.'],
    ['아빠','(아빠가 눈을 감는다.)\n…그래. 열매부터.']],()=>{refreshGoal();next?.();});
}
Rg.dadComesBack=dadComesBack;

/* ---------- 영산 사연 (결정 D-120) ----------
   결정 D-436·D-437: 아빠는 강철이에게 이름을 먹혀 넋이 빠졌다가, 봄에 이름을 되찾는다. 넋이 빠진 동안은 버릇만 보이고,
   되찾은 뒤에는 짧게 끊어 말한다(npcs.csv 말투).
   ① 아빠: 겨울 막대(넋 빠진 동안) → 녹은 땅의 그림 → 수첩의 손도장
   ② 날쌘과 아빠: 아이가 둘 사이에서 말을 나르는 보부상이 된다 (날쌘의 고백 D-03 뒤)
   ③ 늙은 까치: 아빠 소식 부치기 → 엄마의 답 → 마지막 남쪽 길 (아래 길손 블록) */
// 옹달샘 표주박 그림: 박 두 덩이, 나무 마개, 엄마 매듭으로 묶은 끈
defineIcons({bingeo:P=>{
  P(3,7,9,3,'#c9d6dc');P(2,8,1,1,'#c9d6dc');P(4,6,6,1,'#dfe8ec');P(4,10,6,1,'#9fb3bc');P(12,6,1,5,'#9fb3bc');P(13,5,1,2,'#9fb3bc');P(13,10,1,2,'#9fb3bc');
  P(4,8,1,1,'#2b2b33');P(6,8,5,1,'#eef4f6');
},ongdal_gourd:P=>{
  P(6,2,4,3,'#d8b968');P(5,5,6,3,'#d8b968');P(4,8,8,6,'#c9a45a');P(5,13,6,1,'#9c7a3a');P(5,9,2,3,'#e8d08a');
  P(7,1,2,2,'#7a5434');P(4,7,8,1,'#8a3b2a');P(11,7,2,1,'#8a3b2a');P(12,8,1,2,'#8a3b2a');P(11,10,2,1,'#8a3b2a');
}});
function dadArcChoices(){
  const F=G.f,c=[];if(!arcs()||!F.dadDone)return c;
  // 결정 D-436: 넋이 빠진 동안은 아빠 곁의 겨울 막대만 볼 수 있다. 나머지는 이름을 되찾은 뒤(D-437)
  if(!Rg.namesBack()){
    if(!F.yArcsDad1)c.push({t:'아빠 곁에 꽂힌 막대를 본다',go:dadArcTally});
    return c;
  }
  if(F.dadBack&&!F.yArcsDad2)c.push({t:'녹은 물가에 쪼그려 앉은 아빠 곁에 간다',go:dadArcMud});
  else if(F.yArcsDad2&&F.yakDone&&!F.yArcsDad3)c.push({t:'아빠 앞에 수첩을 펼친다',go:dadArcPalm});
  if(F.yArcsNalDad1&&!F.yArcsNalDad2)c.push({t:'산에서 주운 대추를 건넨다',go:nalDadArcJujube});
  if(has('sinpyo')&&!F.yArcsDadSinpyo)c.push({t:'보따리 끈의 신표를 풀어 내민다',go:dadArcSinpyo});
  if(F.yOngdal4&&F.sangunMet&&!F.yOngdal5&&has('ongdal_gourd'))c.push({t:'옹달샘 표주박을 보여 준다',go:ongdalArcDad});
  return c;
}
// 아빠의 신표는 지난가을 큰 장터 문간의 짠돌에게 갔다(jangteo ⑤). 아이가 제 신표를 드리려 하자 아빠는 도로 매 준다.
function dadArcSinpyo(){
  const F=G.f,jj=!!F.jangteoArcsJj4;
  // 결정 D-581: 영산 사연은 막마다 해야 할 말과 몸짓만 남긴다 (사용자 피드백 2026-11-04)
  arcScene('yArcsDadSinpyo',[
    ['너구리','(보따리 끈에서 신표를 풀었다.)\n아빠, 이거요. 부엉 영감님이 주셨어요.'],
    ['너구리',jj?'아빠 신표는 짠돌 아저씨한테 있잖아요.\n이거 아빠가 하세요.':'아빠 허리춤엔 신표가 없네요.\n이거 아빠가 하세요.'],
    ...(jj?[['아빠','(짠돌이라는 이름에 아빠가 눈을 감는다.)\n…거기 있으면 됐다.']]:[]),
    ['아빠','(아빠가 신표를 한참 들여다보더니\n내 보따리 끈에 도로 매 준다. 두 번 감고, 한 번 당겨.)'],
    ['아빠','네 거다.']],
    '아빠에게 내 신표를 드리려 했다. 아빠는 한참 들여다보더니 내 보따리 끈에 도로 매 주고, 네 거라고 했다.',
    ()=>learn('dad:sinpyo'));
}
// ① 겨울 막대: 넋이 빠진 아빠는 버릇처럼 날마다 금을 긋는다. 편지의 "눈 오기 전에 돌아가마"(D-36)를 지키지 못했다.
function dadArcTally(){
  arcScene('yArcsDad1',[
    ['너구리','(아빠 옆 눈 속에 꽂힌 막대에 금이 촘촘하다.\n가을부터… 하루에 하나씩.)'],
    ['아빠','(아빠 엄지가 금을 쓸고 내려가다\n유난히 깊은 금에서 멈춘다. 그러고는 지나간다.)'],
    ['너구리',G.f.salgDone?'(깊은 금. …그놈한테 간 날일까.)':'(깊은 금. …무슨 날이었을까.)'],
    ['너구리','편지에 그랬잖아요. 눈 오기 전에 온다고.\n그 눈이 다 녹고 또 내렸어요. …엄마도 저도 기다렸어요.'],   // 결정 D-527: 아빠는 작년 가을에 떠났다
    ['너구리','(아빠 금 아래에 손톱으로 금을 하나 그었다.\n오늘 몫이다.)'],
    ['아빠','(아빠 엄지가 내 금 앞에서 잠깐 멈춘다.\n그러고는 다시 제 금을 긋는다.)']],
    '아빠 곁 막대에 금이 촘촘했다. 가을부터 하루에 하나씩. 깊은 금 하나에서 아빠 엄지가 멈췄다가 지나갔다. 오늘 몫은 내가 그었다. 아빠 엄지가 내 금 앞에서 잠깐 멈췄다.',
    ()=>learn('dad:tally'));
}
// ② 녹은 땅의 그림: 이름을 되찾은 뒤. 아빠는 말수가 적다. 말 대신 흙에 그린다.
function dadArcMud(){
  arcScene('yArcsDad2',[
    ['너구리','(녹은 물가에서 아빠가 잔가지로 흙을 긋는다.\n큰 너구리 하나, 작은 너구리 하나.)'],
    ['아빠','(손이 한참 멈췄다가, 둘 사이에 하나를 더 그린다.\n셋 위에 지붕, 지붕 위로 연기 한 줄.)'],
    ['너구리','엄마다.'],
    ...(G.f.dolneomeo_turtle1?[['너구리','(돌너머 성황당 가장 높은 가지의 흙빛 천.\n아빠가 말 안 한 소원이… 이거였을까.)']]:[]),
    ['너구리','(모자를 벗어 내밀었다.)\n아빠 거잖아요. 돌려드릴게요.'],
    ['아빠','쓰고 가.'],
    ['아빠','(아빠가 모자를 도로 눌러 씌우고\n챙을 내 눈썹 위에 맞춰 준다.)']],
    '봄이 온 물가에서 아빠가 흙에 그림을 그렸다. 큰 너구리, 작은 너구리, 그 사이에 엄마. 지붕과 연기. 모자를 돌려드리려 했더니 아빠가 쓰고 가라며 도로 씌워 주었다.',
    ()=>learn('dad:mud'));
}
// ③ 수첩의 손도장: 약을 지은 뒤. 젊은 아빠가 길마다 남긴 손바닥 도장과 같은 손이다.
